{"__dsh_paper":"ir-container-v1","entries":[{"kind":"SymbolSpec","value":{"symbol_id":"S-N","scope_ref":"P1","token":"n","meaning":"样本量","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-C","scope_ref":"P1","token":"c","meaning":"拒收临界值（不合格品数阈值）","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-X","scope_ref":"P1","token":"X","meaning":"样本中不合格品数","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-P0","scope_ref":"P1","token":"p_0","meaning":"标称次品率","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-ALPHA","scope_ref":"P1","token":"alpha","meaning":"第一类错误概率上限（显著性水平）","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-BETA","scope_ref":"P1","token":"beta","meaning":"第二类错误概率上限","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-ALPHA-ACTUAL","scope_ref":"P1","token":"***","meaning":"实际第一类错误率","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-BETA-ACTUAL","scope_ref":"P1","token":"***","meaning":"实际第二类错误率","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-P1","scope_ref":"P2","token":"p_1","meaning":"零配件1的次品率","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-P2","scope_ref":"P2","token":"p_2","meaning":"零配件2的次品率","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PF","scope_ref":"P2","token":"p_f","meaning":"成品的条件次品率","unit":"dimensionless","role":"PARAMETER","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CP1","scope_ref":"P2","token":"c_p1","meaning":"零配件1的购买单价","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CP2","scope_ref":"P2","token":"c_p2","meaning":"零配件2的购买单价","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CT1","scope_ref":"P2","token":"c_t1","meaning":"零配件1的检测成本","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CT2","scope_ref":"P2","token":"c_t2","meaning":"零配件2的检测成本","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CA","scope_ref":"P2","token":"c_a","meaning":"装配成本","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CTF","scope_ref":"P2","token":"c_tf","meaning":"成品检测成本","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CD","scope_ref":"P2","token":"c_d","meaning":"拆解费用","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CS","scope_ref":"P2","token":"c_s","meaning":"报废损失","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-CR","scope_ref":"P2","token":"c_r","meaning":"市场调换损失","unit":"元/件","role":"PARAMETER","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-D1","scope_ref":"P2","token":"d_1","meaning":"零配件1检测决策","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-D2","scope_ref":"P2","token":"d_2","meaning":"零配件2检测决策","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-DF","scope_ref":"P2","token":"d_f","meaning":"成品检测决策","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-DS","scope_ref":"P2","token":"d_s","meaning":"不合格成品拆解决策","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E","scope_ref":"P2","token":"E","meaning":"单件成品的期望总成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E-OPT","scope_ref":"P2","token":"E_opt","meaning":"最优策略下的最小期望总成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-STRATEGY-Q2","scope_ref":"P2","token":"***","meaning":"问题2最优策略编码","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E3","scope_ref":"P3","token":"E3","meaning":"问题3最优策略下的最小期望总成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-STRATEGY-Q3","scope_ref":"P3","token":"***","meaning":"问题3最优策略编码","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"INTEGER","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E4-Q2-LO","scope_ref":"P4","token":"***","meaning":"问题4中问题2次品率取下界时的最优期望成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E4-Q2-HI","scope_ref":"P4","token":"***","meaning":"问题4中问题2次品率取上界时的最优期望成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E4-Q3-LO","scope_ref":"P4","token":"***","meaning":"问题4中问题3次品率取下界时的最优期望成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-E4-Q3-HI","scope_ref":"P4","token":"***","meaning":"问题4中问题3次品率取上界时的最优期望成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-ROBUST-Q2","scope_ref":"P4","token":"***","meaning":"问题2决策稳健性标志（1=稳健，0=不稳健）","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-ROBUST-Q3","scope_ref":"P4","token":"***","meaning":"问题3决策稳健性标志（1=稳健，0=不稳健）","unit":"dimensionless","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEPENDENT-DEFECTS","scope_ref":"P1","statement":"各零配件、半成品、成品的次品事件相互独立，即一个零配件是否合格不影响另一个零配件是否合格，也不影响装配过程中是否产生新的次品","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"各零配件、半成品、成品的次品事件相互独立，即一个零配件是否合格不影响另一个零配件是否合格，也不影响装配过程中是否产生新的次品"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-STEADY-STATE","scope_ref":"P1","statement":"生产过程处于稳态，次品率、成本参数在决策周期内保持不变，且每批零配件的次品率与标称值或抽样估计值一致","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"生产过程处于稳态，次品率、成本参数在决策周期内保持不变，且每批零配件的次品率与标称值或抽样估计值一致"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INFINITE-LOOP-CLOSURE","scope_ref":"P1","statement":"拆解回流和调换回流形成的递归过程可以按期望值闭合求解，即拆解后的零配件按原次品率重新进入流程，调换回来的不合格品按相同规则处理，递归的期望成本收敛为几何级数","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"拆解回流和调换回流形成的递归过程可以按期望值闭合求解，即拆解后的零配件按原次品率重新进入流程，调换回来的不合格品按相同规则处理，递归的期望成本收敛为几何级数"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-RISK-NEUTRAL","scope_ref":"P1","statement":"企业以期望总成本最小化为决策目标，不考虑风险偏好或效用函数的非线性","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"企业以期望总成本最小化为决策目标，不考虑风险偏好或效用函数的非线性"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-EXACT-BINOMIAL","scope_ref":"P1","statement":"抽样检测中每件零配件的检测结果相互独立且服从相同的伯努利分布，样本不合格品数精确服从二项分布，不使用正态近似","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"抽样检测中每件零配件的检测结果相互独立且服从相同的伯努利分布，样本不合格品数精确服从二项分布，不使用正态近似"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-P0-AS-BOUNDARY","scope_ref":"P1","statement":"标称值 10% 是次品率的上界，情形(2)中"次品率不超过标称值"的最不利情况恰好在 p = 10% 处取得，因此样本量计算以 p = 10% 为基准","source_type":"DERIVED","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"标称值 10% 是次品率的上界，情形(2)中"次品率不超过标称值"的最不利情况恰好在 p = 10% 处取得，因此样本量计算以 p = 10% 为基准"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-DISASSEMBLY-NO-DAMAGE","scope_ref":"P2","statement":"拆解过程不会对零配件造成损坏，拆解后的零配件次品率与原始零配件相同，可以按原次品率重新进入检测和装配流程","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"拆解过程不会对零配件造成损坏，拆解后的零配件次品率与原始零配件相同，可以按原次品率重新进入检测和装配流程"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-RETURN-REPEAT","scope_ref":"P2","statement":"用户退回的不合格品按与出厂不合格品相同的规则处理，即重复拆解决策，且退回的不合格品数量与流入市场的不合格品数量成正比","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"用户退回的不合格品按与出厂不合格品相同的规则处理，即重复拆解决策，且退回的不合格品数量与流入市场的不合格品数量成正比"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SINGLE-BATCH","scope_ref":"P2","statement":"问题2中的决策针对单件成品的期望成本进行优化，不考虑批量效应或库存成本，所有成本参数按"元/件"计","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"问题2中的决策针对单件成品的期望成本进行优化，不考虑批量效应或库存成本，所有成本参数按"元/件"计"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-CONDITIONAL-DEFECT-RATE","scope_ref":"P3","statement":"半成品和成品的次品率是在所有输入零配件或半成品均为正品的条件下的条件次品率，即表2中给出的次品率已经排除了输入件不合格的情况","source_type":"GIVEN","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"半成品和成品的次品率是在所有输入零配件或半成品均为正品的条件下的条件次品率，即表2中给出的次品率已经排除了输入件不合格的情况"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-TREE-INDEPENDENCE","scope_ref":"P3","statement":"树形结构中不同分支的次品事件相互独立，一个半成品的次品率不受其他半成品是否合格的影响","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"树形结构中不同分支的次品事件相互独立，一个半成品的次品率不受其他半成品是否合格的影响"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-ENUMERABLE-POLICY-SPACE","scope_ref":"P3","statement":"对于问题3的具体案例，策略空间（8 个零配件检测决策 + 3 个半成品检测决策 + 1 个成品检测决策 + 4 个拆解决策 = 2^16 = 65536 种策略）在计算上可枚举，不需要启发式搜索","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"对于问题3的具体案例，策略空间（8 个零配件检测决策 + 3 个半成品检测决策 + 1 个成品检测决策 + 4 个拆解决策 = 2^16 = 65536 种策略）在计算上可枚举，不需要启发式搜索"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-CI-FROM-Q1","scope_ref":"P4","statement":"问题4中次品率的置信区间由问题1的抽样方案确定，即使用固定样本量二项检验的置信区间，而非其他方法构造的置信区间","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":f