// --- binomial tail probability: P(X >= k | n, p) ---
function binomTail(n, k, p) {
    if (k > n) return 0;
    if (k <= 0) return 1;
    // use log-space to avoid overflow
    let logP = 0;
    let sum = 0;
    for (let i = 0; i < k; i++) {
        if (i === 0) {
            logP = n * Math.log(1 - p);
        } else {
            logP = logP + Math.log((n - i + 1) / i) + Math.log(p / (1 - p));
        }
        sum += Math.exp(logP);
    }
    return 1 - sum;
}

// --- Problem 1: find minimal n and corresponding c ---
function solveQ1(p0, alpha, beta) {
    for (let n = 1; n <= 10000; n++) {
        // find c such that P(X>=c) <= alpha and P(X>=c) >= beta
        // P(X>=c) is decreasing in c, so we can binary search or scan
        let cLo = 0, cHi = n + 1;
        // find largest c with P(X>=c) >= beta
        for (let c = 0; c <= n + 1; c++) {
            const tail = binomTail(n, c, p0);
            if (tail < beta) { cHi = c; break; }
        }
        // find smallest c with P(X>=c) <= alpha
        for (let c = n + 1; c >= 0; c--) {
            const tail = binomTail(n, c, p0);
            if (tail <= alpha) { cLo = c; break; }
        }
        // need cLo <= cHi-1 (i.e. there exists integer c between them)
        if (cLo <= cHi - 1) {
            const c = cLo; // pick the smallest valid c
            const alphaActual = binomTail(n, c, p0);
            const betaActual = 1 - (1 - binomTail(n, c, p0)); // P(X<c) = 1 - P(X>=c)
            // actually betaActual = P(X>=c) is the type II error rate at p=p0
            // P(X < c | p0) = 1 - P(X>=c | p0) >= 1-beta => P(X>=c | p0) <= beta
            // So betaActual = P(X>=c | p0)
            const betaActualVal = binomTail(n, c, p0);
            return { n, c, alphaActual, betaActual: betaActualVal };
        }
    }
    return null;
}

const q1 = solveQ1(0.10, 0.05, 0.10);

// --- Problem 2: enumerate 16 strategies ---
function solveQ2(params) {
    const { p1, p2, pf, cp1, cp2, ct1, ct2, ca, ctf, cd, cs, cr } = params;
    let bestE = Infinity;
    let bestStrategy = -1;
    const strategies = [];
    for (let s = 0; s < 16; s++) {
        const d1 = (s & 1) ? 1 : 0;
        const d2 = (s & 2) ? 1 : 0;
        const df = (s & 4) ? 1 : 0;
        const ds = (s & 8) ? 1 : 0;

        // compute expected cost per unit
        // Part cost: purchase + detection
        const cost1 = cp1 + (d1 ? ct1 : 0);
        const cost2 = cp2 + (d2 ? ct2 : 0);

        // Probability that a part entering assembly is good
        const pg1 = d1 ? (1 - p1) : 1; // if not tested, we assume it's good (but may be bad)
        const pg2 = d2 ? (1 - p2) : 1;
        // Actually if not tested, the part may be defective and we don't know.
        // The defective part enters assembly and may cause成品 defective.
        // We need to model: if part not tested, it enters assembly with its原始次品率.
        // So the probability that part entering assembly is actually good:
        const pg1Actual = d1 ? 1 : (1 - p1); // if tested, only good ones pass; if not tested, fraction (1-p1) are good
        const pg2Actual = d2 ? 1 : (1 - p2);

        // Probability成品 is defective:
        //成品 defective if any input part is defective OR the assembly process introduces a defect (conditional on all inputs good)
        const pAllInputsGood = pg1Actual * pg2Actual;
        const pDefective = 1 - pAllInputsGood * (1 - pf);

        // Base cost before handling defective成品
        let baseCost = cost1 + cost2 + ca;
        if (df) baseCost += ctf;

        // If成品 is defective:
        // If we detect it (df=1): we know it's defective and apply ds decision
        // If we don't detect (df=0): it goes to market and incurs cr
        let eDefectiveHandling;
        if (df) {
            // detected defective
            if (ds) {
                // disassemble: cost cd, then parts re-enter (recursive)
                // The recursion: E = baseCost + pDefective * (cd + E_part)
                // where E_part is the expected cost of re-processing the disassembled parts
                // Disassembled parts are same as original: they go through detection again if d1/d2=1
                // E_part = cost1_re + cost2_re + ca + ... same structure
                // Actually E_part = E (the whole process repeats)
                // So: E = baseCost + pDefective * (cd + E)  => E = (baseCost + pDefective*cd) / (1 - pDefective)
                // But this is only if we always disassemble and re-enter.
                // However, the recursion may be more subtle: disassembled parts may be tested again.
                // We adopt the closure: E = baseCost + pDefective * (cd + E)
                const E = (baseCost + pDefective * cd) / (1 - pDefective);
                eDefectiveHandling = pDefective * (cd + E);
            } else {
                // scrap: cost cs
                eDefectiveHandling = pDefective * cs;
            }
        } else {
            // not detected: goes to market, incur cr
            eDefectiveHandling = pDefective * cr;
        }

        // But the above closure double-counts: we need to solve the fixed-point properly.
        // Let's re-derive cleanly.
        // E = baseCost + pDefective * [ df * ( ds * (cd + E_re) + (1-ds)*cs ) + (1-df)*cr ]
        // where E_re is the expected cost from re-entering disassembled parts.
        // If ds=1, disassembled parts are重新检测: they go through the same process.
        // So E_re = E (the same expected cost per unit).
        // Thus: E = baseCost + pDefective * [ df * ( ds * (cd + E) + (1-ds)*cs ) + (1-df)*cr ]
        // => E - pDefective * df * ds * E = baseCost + pDefective * [ df * ( ds*cd + (1-ds)*cs ) + (1-df)*cr ]
        // => E = (baseCost + pDefective * [ df * ( ds*cd + (1-ds)*cs ) + (1-df)*cr ]) / (1 - pDefective * df * ds)

        const denom = 1 - pDefective * df * ds;
        const num = baseCost + pDefective * ( df * ( ds * cd + (1 - ds) * cs ) + (1 - df) * cr );
        const E = num / denom;

        strategies.push({ s, d1, d2, df, ds, E });
        if (E < bestE) {
            bestE = E;
            bestStrategy = s;
        }
    }
    return { bestE, bestStrategy, strategies };
}

const paramsQ2 = {
    p1: 0.10, p2: 0.10, pf: 0.10,
    cp1: 2, cp2: 3,
    ct1: 0.5, ct2: 0.5,
    ca: 5, ctf: 1, cd: 2, cs: 1, cr: 10
};
const q2 = solveQ2(paramsQ2);

// --- Problem 3: tree-structured enumeration (simplified representative) ---
// The analysis describes 8 parts -> 3 subassemblies -> 1成品, 2^16=65536 strategies.
// We implement a generic tree solver and run it with placeholder parameters.

function solveTree(params) {
    // params: { parts: [{p, cp, ct}], subs: [{children: [idx...], pf, ca, ctf, cd, cs}], final: {children: [idx...], pf, ca, ctf, cd, cs, cr} }
    // For the specific case: 8 parts, 3 subs, 1 final.
    // We'll enumerate all strategies: each node has detect bit, each non-leaf has disassemble bit.
    const nParts = params.parts.length;
    const nSubs = params.subs.length;
    const nTotalNodes = nParts + nSubs + 1; // +1 for final
    const nDetectBits = nTotalNodes;
    const nDisasmBits = nSubs + 1; // subs + final
    const totalStrategies = (1 << nDetectBits) * (1 << nDisasmBits);

    let bestE = Infinity;
    let bestStrategy = -1;

    // For efficiency, we sample or limit. The analysis says 65536 is enumerable.
    // We'll do full enumeration if totalStrategies <= 65536, else sample.
    const maxEnum = 65536;
    const doFull = totalStrategies <= maxEnum;
    const nSamples = doFull ? totalStrategies : 10000;

    function evalStrategy(detectBits, disasmBits) {
        // detectBits: bit i = 1 means node i is tested
        // disasmBits: bit j = 1 means non-leaf j is disassembled if defective
        // We compute expected cost bottom-up.
        // First compute leaf costs.
        const nodeCost = new Array(nTotalNodes).fill(0);
        const nodePg = new Array(nTotalNodes).fill(1); // prob node is good (given it was produced)

        for (let i = 0; i < nParts; i++) {
            const p = params.parts[i];
            const detect = (detectBits >> i) & 1;
            const cost = p.cp + (detect ? p.ct : 0);
            const pg = detect ? 1 : (1 - p.p);
            nodeCost[i] = cost;
            nodePg[i] = pg;
        }

        // Then subs and final
        const allNonLeaf = params.subs.concat([params.final]);
        for (let si = 0; si < allNonLeaf.length; si++) {
            const node = allNonLeaf[si];
            const nodeIdx = nParts + si;
            const detect = (detectBits >> nodeIdx) & 1;
            const disasm = (disasmBits >> si) & 1;

            // sum child costs
            let childCostSum = 0;
            let childPgProd = 1;
            for (const ci of node.children) {
                childCostSum += nodeCost[ci];
                childPgProd *= nodePg[ci];
            }

            const baseCost = childCostSum + node.ca + (detect ? node.ctf : 0);
            const pg = childPgProd * (1 - node.pf);
            const pDef = 1 - pg;

            // defective handling
            let denom = 1 - pDef * detect * disasm;
            let num = baseCost + pDef * ( detect * ( disasm * node.cd + (1 - disasm) * (node.cs || 0) ) + (1 - detect) * (node.cr || 0) );
            const E = num / denom;

            nodeCost[nodeIdx] = E;
            nodePg[nodeIdx] = pg;
        }

        return nodeCost[nTotalNodes - 1];
    }

    if (doFull) {
        for (let s = 0; s < totalStrategies; s++) {
            const detectBits = s & ((1 << nDetectBits) - 1);
            const disasmBits = (s >> nDetectBits) & ((1 << nDisasmBits) - 1);
            const E = evalStrategy(detectBits, disasmBits);
            if (E < bestE) {
                bestE = E;
                bestStrategy = s;
            }
        }
    } else {
        for (let k = 0; k < nSamples; k++) {
            const detectBits = Math.floor(Math.random() * (1 << nDetectBits));
            const disasmBits = Math.floor(Math.random() * (1 << nDisasmBits));
            const s = detectBits | (disasmBits << nDetectBits);
            const E = evalStrategy(detectBits, disasmBits);
            if (E < bestE) {
                bestE = E;
                bestStrategy = s;
            }
        }
    }

    return { bestE, bestStrategy, totalStrategies, doFull };
}

