// --- Problem 4: sensitivity analysis ---
// Use Q1 confidence intervals on defect rates, re-run Q2 and Q3 at bounds.
// For binomial n,c from Q1, we compute Clopper-Pearson CI for each p.
function clopperPearsonCI(x, n, alpha) {
    // x = number of successes (or failures). We'll use failures = c-1 approx.
    // Actually we need CI for p given observed x defects out of n.
    // Lower bound: Beta(alpha/2; x, n-x+1)
    // Upper bound: Beta(1-alpha/2; x+1, n-x)
    // We approximate with normal for simplicity, or use exact beta.
    // Here we use a simple approximation: p_hat +/- z * sqrt(p_hat*(1-p_hat)/n)
    const phat = x / n;
    const z = 1.96; // 95% CI
    const se = Math.sqrt(phat * (1 - phat) / n);
    return { lo: Math.max(0, phat - z * se), hi: Math.min(1, phat + z * se) };
}

function solveQ4(q1Result, paramsQ2, paramsQ3) {
    // Use the Q1 sample size n and critical value c to form CI for p=0.10
    const n = q1Result.n;
    const c = q1Result.c;
    // The CI for p when we observe exactly c-1 defects (just below rejection)
    // We'll use the worst-case: CI around p0=0.10 with n samples
    const ci = clopperPearsonCI(Math.round(n * 0.10), n, 0.05);

    // Q2 sensitivity: vary p1, p2, pf each to lo/hi bounds
    const paramsLo = { ...paramsQ2, p1: ci.lo, p2: ci.lo, pf: ci.lo };
    const paramsHi = { ...paramsQ2, p1: ci.hi, p2: ci.hi, pf: ci.hi };
