    const q2Hi = solveQ2(paramsHi);
    const robustQ2 = (q2Lo.bestStrategy === q2Hi.bestStrategy) ? 1 : 0;

    // Q3 sensitivity
    const paramsQ3Lo = JSON.parse(JSON.stringify(paramsQ3));
    const paramsQ3Hi = JSON.parse(JSON.stringify(paramsQ3));
    for (const part of paramsQ3Lo.parts) part.p = ci.lo;
