-RISK-NEUTRAL","A-DISASSEMBLY-NO-DAMAGE","A-RETURN-REPEAT","A-CONDITIONAL-DEFECT-RATE","A-TREE-INDEPENDENCE","A-ENUMERABLE-POLICY-SPACE"],"variable_refs":["S-E3","S-STRATEGY-Q3"],"parameter_refs":[],"equation_refs":["EQ-LEAF","EQ-TREE-RECURSIVE"],"constraints":[],"objective":"minimize expected total cost over all 65536 strategies for the 2-stage 8-part tree","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-INDEPENDENT-DEFECTS","A-STEADY-STATE","A-INFINITE-LOOP-CLOSURE","A-RISK-NEUTRAL","A-DISASSEMBLY-NO-DAMAGE","A-RETURN-REPEAT","A-CI-FROM-Q1","A-INDEPENDENT-ESTIMATES","A-WORST-CASE-BOUNDARY"],"variable_refs":["S-E4-Q2-LO","S-E4-Q2-HI","S-E4-Q3-LO","S-E4-Q3-HI","S-ROBUST-Q2","S-ROBUST-Q3"],"parameter_refs":[],"equation_refs":[],"constraints":[],"objective":"assess robustness of Q2 and Q3 optimal strategies under CI bounds from Q1","dependencies":["M2","M3"]}}],"code":"const fs = require('fs');

// --- binomial helpers ---
function logChoose(n, k) {
    if (k < 0 || k > n) return -Infinity;
    if (k === 0 || k === n) return 0;
    let s = 0;
    for (let i = 1; i <= k; i++) s += Math.log(n - k + i) - Math.log(i);
    return s;
}

function binomPMF(n, p, k) {
    const lc = logChoose(n, k);
    if (lc === -Infinity) return 0;
    return Math.exp(lc + k * Math.log(p) + (n - k) * Math.log(1 - p));
}

function binomTail(n, p, c) {
    // P(X >= c)
    let s = 0;
    for (let k = c; k <= n; k++) s += binomPMF(n, p, k);
    return s;
}

// --- Q1: find minimal n and c ---
const p0 = 0.10;
const alpha = 0.05;
const beta = 0.10;

let n_fixed = null, c_fixed = null;
for (let n = 1; n <= 5000; n++) {
    let found = false;
    for (let c = 0; c <= n; c++) {
        const tail = binomTail(n, p0, c);
        if (tail <= alpha && tail >= beta) {
            n_fixed = n;
            c_fixed = c;
            found = true;
            break;
        }
    }
    if (found) break;
}

const alpha_actual = binomTail(n_fixed, p0, c_fixed);
const beta_actual = 1 - binomTail(n_fixed, p0, c_fixed + 1);

// --- Q2: 16-strategy enumeration ---
const p1 = 0.10, p2 = 0.10, pf = 0.10;
const cp1 = 2, cp2 = 3, ct1 = 1, ct2 = 1, ctf = 2, ca = 5, cd = 4, cs = 2, cr = 10;

function evalQ2(d1, d2, df, ds) {
    // effective cost of a part given its defect rate p, purchase cost cp, test cost ct, test decision d
    function partCost(p, cp, ct, d) {
        if (d === 1) {
            // test: pay ct, if defective (p) scrap and buy again (recurse)
            // E = ct + (1-p)*cp + p*(cp + E)  => E = (ct + cp) / (1-p)
            return (ct + cp) / (1 - p);
        } else {
            // no test: just buy, defective ones flow through
            return cp;
        }
    }

    const e1 = partCost(p1, cp1, ct1, d1);
    const e2 = partCost(p2, cp2, ct2, d2);

    // probability that both parts are good (if untested, they may be defective)
    const pg1 = (d1 === 1) ? 1 : (1 - p1);
    const pg2 = (d2 === 1) ? 1 : (1 - p2);
    const pBothGood = pg1 * pg2;

    // assembly cost always paid
    let E = e1 + e2 + ca;

    // probability final product is defective
    const pDef = 1 - pBothGood * (1 - pf);

    if (df === 1) {
        // test final product
        E += ctf;
        if (ds === 1) {
            // disassemble defective ones
            E += pDef * (cd + e1 + e2);
        } else {
            // scrap defective ones
            E += pDef * cs;
        }
    } else {
        // no final test: defective products reach market
        E += pDef * cr;
    }

    return E;
}

let bestE2 = Infinity, bestStrat2 = -1;
for (let s = 0; s < 16; s++) {
    const d1 = (s >> 0) & 1;
    const d2 = (s >> 1) & 1;
    const df = (s >> 2) & 1;
    const ds = (s >> 3) & 1;
    const e = evalQ2(d1, d2, df, ds);
    if (e < bestE2) { bestE2 = e; bestStrat2 = s; }
}

// --- Q3: 2-stage 8-part tree enumeration ---
// Structure: 8 parts -> 3 subassemblies -> 1 final
// Parts 1-3 -> SA1, Parts 4-5 -> SA2, Parts 6-8 -> SA3
// SA1, SA2, SA3 -> Final

// Default parameters (placeholder values from typical problem data)
const partDefRates = [0.10, 0.10, 0.10, 0.10, 0.10, 0.10, 0.10, 0.10];
const partBuyCosts = [2, 2, 2, 3, 3, 2, 2, 2];
const partTestCosts = [1, 1, 1, 1, 1, 1, 1, 1];
const saDefRates = [0.10, 0.10, 0.10];
const saAssemblyCosts = [3, 3, 3];
const saTestCosts = [2, 2, 2];
const saDisassembleCosts = [4, 4, 4];
const saScrapCosts = [2, 2, 2];
const finalDefRate = 0.10;
const finalAssemblyCost = 5;
const finalTestCost = 2;
const finalDisassembleCost = 4;
const finalScrapCost = 2;
const marketReturnCost = 10;

// children of each subassembly
const saChildren = [[0,1,2],[3,4],[5,6,7]];

function evalQ3(strat) {
    // strat: bits 0-7 = part tests, 8-10 = SA tests, 11 = final test, 12-14 = SA disassemble, 15 = final disassemble
    const partTests = [];
    for (let i = 0; i < 8; i++) partTests.push((strat >> i) & 1);
    const saTests = [];
    for (let i = 0; i < 3; i++) saTests.push((strat >> (8 + i)) & 1);
    const finalTest = (strat >> 11) & 1;
    const saDis = [];
    for (let i = 0; i < 3; i++) saDis.push((strat >> (12 + i)) & 1);
    const finalDis = (strat >> 15) & 1;

    // leaf part costs
    function partCost(i) {
        const p = partDefRates[i];
        const cp = partBuyCosts[i];
        const ct = partTestCosts[i];
        const d = partTests[i];
        if (d === 1) return (ct + cp) / (1 - p);
        else return cp;
    }

    const partECs = [];
    for (let i = 0; i < 8; i++) partECs.push(partCost(i));

    // subassembly costs
    function saCost(saIdx) {
        const children = saChildren[saIdx];
        let childSum = 0;
        let pAllGood = 1;
        for (const ci of children) {
            childSum += partECs[ci];
            if (partTests[ci] === 1) pAllGood *= 1;
            else pAllGood *= (1 - partDefRates[ci]);
        }
        let E = childSum + saAssemblyCosts[saIdx];
        const pDef = 1 - pAllGood * (1 - saDefRates[saIdx]);
        if (saTests[saIdx] === 1) {
            E += saTestCosts[saIdx];
            if (saDis[saIdx] === 1) {
                E += pDef * (saDisassembleCosts[saIdx] + childSum);
            } else {
                E += pDef * saScrapCosts[saIdx];
            }
        } else {
            // no SA test: defective flows up
        }
        return { cost: E, pGood: saTests[saIdx] === 1 ? 1 : (1 - pDef) };
    }

    const saResults = [];
    for (let i = 0; i < 3; i++) saResults.push(saCost(i));

    // final assembly
    let childSum = 0;
    let pAllGood = 1;
    for (const sr of saResults) {
        childSum += sr.cost;
        pAllGood *= sr.pGood;
    }
    let E = childSum + finalAssemblyCost;
    const pDef = 1 - pAllGood * (1 - finalDefRate);
    if (finalTest === 1) {
        E += finalTestCost;
        if (finalDis === 1) {
            E += pDef * (finalDisassembleCost + childSum);
        } else {
            E += pDef * finalScrapCost;
        }
    } else {
        E += pDef * marketReturnCost;
    }
    return E;
}

let bestE3 = Infinity, bestStrat3 = -1;
for (let s = 0; s < 65536; s++) {
    const e = evalQ3(s);
    if (e < bestE3) { bestE3 = e; bestStrat3 = s; }
}

// --- Q4: sensitivity at CI bounds ---
// Use Clopper-Pearson 95% CI for binomial proportion with n_fixed samples
// For simplicity, approximate CI: p_hat +/- 1.96 * sqrt(p_hat*(1-p_hat)/n)
// But since we don't have observed data, use the worst-case CI around p0=0.10
// CI bounds for p=0.10 with n_fixed samples (Clopper-Pearson)
function clopperPearson(n, x, conf) {
    // x = number of successes (defects)
    const alpha = (1 - conf) / 2;
    // lower bound: beta quantile
    function betaQuantile(a, b, p) {
        // simple bisection
        let lo = 0, hi = 1;
        for (let iter = 0; iter < 100; iter++) {
            const mid = (lo + hi) / 2;
            // regularized incomplete beta via continued fraction
            function regBeta(x, a, b) {
                if (x === 0) return 0;
                if (x === 1) return 1;
                const lnBeta = lgamma(a) + lgamma(b) - lgamma(a + b);
                // use series expansion at x
                let sum = 0;
                let term = Math.exp(a * Math.log(x) + b * Math.log(1 - x) - lnBeta + Math.log(1 / a));
                for (let k = 0; k < 200; k++) {
                    sum += term;
                    term *= (a + b + k) / (a + k + 1) * x;
                    if (term < 1e-16) break;
                }
                return sum;
            }
            const val = regBeta(mid, a, b);
            if (val < p) lo = mid; else hi = mid;
        }
        return (lo + hi) / 2;
    }
    function lgamma(z) {
        let s = 0;
        s += (z + 0.5) * Math.log(z + 5.5) - (z + 5.5);
        s += Math.log(2.5066282746310005 * (1 + 1 / (12 * (z + 0.5))));
        return s;
    }
    const lo = (x === 0) ? 0 : betaQuantile(x, n - x + 1, alpha);
    const hi = (x === n) ? 1 : betaQuantile(x + 1, n - x, 1 - alpha);
    return [lo, hi];
}

// Use expected number of defects = n * p0
const xExp = Math.round(n_fixed * p0);
const ci = clopperPearson(n_fixed, xExp, 0.95);
const pLo = ci[0], pHi = ci[1];

