function evalQ2WithRates(pp1, pp2, ppf) {
    function partCost(p, cp, ct, d) {
        if (d === 1) return (ct + cp) / (1 - p);
        else return cp;
    }
    let bestE = Infinity;
    for (let s = 0; s < 16; s++) {
        const d1 = (s >> 0) & 1;
        const d2 = (s >> 1) & 1;
        const df = (s >> 2) & 1;
        const ds = (s >> 3) & 1;
        const e1 = partCost(pp1, cp1, ct1, d1);
        const e2 = partCost(pp2, cp2, ct2, d2);
        const pg1 = (d1 === 1) ? 1 : (1 - pp1);
        const pg2 = (d2 === 1) ? 1 : (1 - pp2);
        const pBothGood = pg1 * pg2;
        let E = e1 + e2 + ca;
        const pDef = 1 - pBothGood * (1 - ppf);
        if (df === 1) {
            E += ctf;
            if (ds === 1) E += pDef * (cd + e1 + e2);
            else E += pDef * cs;
        } else {
            E += pDef * cr;
        }
        if (E < bestE) bestE = E;
    }
    return bestE;
}

const e4q2Lo = evalQ2WithRates(pLo, pLo, pLo);
