function evalQ3WithRates(pArr, saPArr, finalP) {
    const partDefRates2 = [pArr[0],pArr[1],pArr[2],pArr[3],pArr[4],pArr[5],pArr[6],pArr[7]];
    const saDefRates2 = [saPArr[0],saPArr[1],saPArr[2]];
