    const partECs = [];
    for (let i = 0; i < 8; i++) partECs.push(partCost(i));
    function saCost(saIdx) {
        const children = saChildren[saIdx];
        let childSum = 0;
        let pAllGood = 1;
        for (const ci of children) {
            childSum += partECs[ci];
            if (((bestStrat3 >> ci) & 1) === 1) pAllGood *= 1;
            else pAllGood *= (1 - partDefRates2[ci]);
        }
        let E = childSum + saAssemblyCosts[saIdx];
